            var grip = document.createElement('span'); grip.className = 'sm-grip'; grip.textContent = '\u2630';
            var barTitle = document.createElement('span'); barTitle.className = 'sm-title'; barTitle.innerText = record.title || ('Chapter ' + (idx + 1));
